script:
const TICKET_TYPE_NOTES = {
  'Attendance Condonation Under AER': '<p><strong>Note:</strong> Your application will be considered at the end of the Trimester only if your attendance in the concerned subject is at least 66%.</p>',
  'OOR Intimation': '<p>No approval required. Ticket will be automatically closed on submission.</p>',
  'Electric Appliance Declaration': '<p>No approval required. Ticket will be automatically closed on submission.</p>',
  'Transcript Request': '<p><strong>Note:</strong> A fee applies for transcript issuance based on the type selected. You will be asked to pay online after submitting this request; the request is processed only after payment is confirmed.</p>',
};

/**
 * Calculate duration between two Frappe Datetime strings 'YYYY-MM-DD HH:MM:SS'.
 * Returns a string like '2h 30m', or '' if inputs are invalid or end <= start.
 */
function calcTripTime(start, end) {
  if (!start || !end) return '';
  var s = new Date(start.replace(' ', 'T'));
  var e = new Date(end.replace(' ', 'T'));
  if (isNaN(s) || isNaN(e) || e <= s) return '';
  var mins = Math.floor((e - s) / 60000);
  return Math.floor(mins / 60) + 'h ' + String(mins % 60).padStart(2, '0') + 'm';
}

async function setupForm({ doc, call, applyFilters, setAbout }) {

  // ── 1. Single API call to get role flags ────────────────────────────────
  var roleCtx = { is_faculty: false, is_student: false, is_enrolled_student: false };
  try {
    roleCtx = await call('helpdesk.api.nls_student.get_user_role_context');
  } catch(e) {
    console.error('NLS: get_user_role_context failed', e);
  }

  // ── 2a. FACULTY branch ───────────────────────────────────────────────────
  if (roleCtx.is_faculty) {

    // Fetch faculty details now (before the setTimeout) so the API call
    // doesn't depend on timing, but assign into doc after a short delay.
    // This is necessary because TicketNew.vue calls setupTemplateFields()
    // synchronously right after setupCustomizations() starts, wiping all
    // doc keys back to ''. Using setTimeout(0) defers our assignments
    // until after that synchronous wipe has completed.
    var tctx = null;
    try {
      tctx = await call('helpdesk.api.nls_student.get_transport_context');
    } catch(e) {
      console.error('NLS: get_transport_context failed', e);
    }

    // Use a small delay to ensure we run after setupTemplateFields wipes doc
    setTimeout(function() {
      doc['ticket_type'] = 'Travel & Transportation';
      if (tctx) {
        doc['custom_transport_requestor']       = tctx['custom_transport_requestor']       || '';
        doc['custom_transport_requestor_email'] = tctx['custom_transport_requestor_email'] || '';
      }
    }, 50);

    // Return only the onChange handlers relevant to faculty
    return {
      onChange: {
        custom_transport_start_time: function(value) {
          doc['custom_transport_trip_time'] =
            calcTripTime(value, doc['custom_transport_end_time'] || '');
        },
        custom_transport_end_time: function(value) {
          doc['custom_transport_trip_time'] =
            calcTripTime(doc['custom_transport_start_time'] || '', value);
        }
      }
    };
  }

  // ── 2b. STUDENT / PACE APPLICANT branch ──────────────────────────────────
  var isStudent = (roleCtx.is_student === true);
  var sctx = null;
  if (isStudent) {
    try {
      sctx = await call('helpdesk.api.nls_student.get_student_context');
    } catch(e) {
      console.error('NLS: get_student_context failed', e);
    }
  }

  // Current-term courses for the Attendance Condonation "Course" field.
  // Fetched once up front so it's ready by the time the student picks
  // 'Attendance Condonation Under AER' as the ticket type.
  var courseOptions = [];
  if (isStudent) {
    try {
      var courses = await call('helpdesk.api.nls_student.get_student_current_term_courses');
      courseOptions = (courses || []).map(function(c) { return c.value; });
    } catch(e) {
      console.error('NLS: get_student_current_term_courses failed', e);
    }
  }

  function applyCourseOptions() {
    if (typeof applyFilters === 'function') {
      applyFilters('custom_condonation_course', courseOptions);
    }
  }

  // "Type of Issue" is a Link to HD Ticket Type Of Issue, scoped to the
  // currently selected ticket_type. link_filters on the Custom Field can't
  // see the form's live ticket_type value, so we resolve the matching
  // issue names via the server and narrow the Link with applyFilters.
  var ISSUE_TICKET_TYPES = ['Academics', 'Facilities', 'Finance', 'IT', 'PACE'];
  async function applyIssueOptionsFor(ticketType) {
    if (typeof applyFilters !== 'function') return;
    if (!ISSUE_TICKET_TYPES.includes(ticketType)) return;
    var names = [];
    try {
      names = await call('helpdesk.api.nls_student.get_issue_names_for_ticket_type', {
        ticket_type: ticketType
      });
    } catch(e) {
      console.error('NLS: get_issue_names_for_ticket_type failed', e);
    }
    applyFilters('custom_type_of_issue', names || []);
  }

  // Defer assignment past setupTemplateFields wipe (same reason as faculty branch)
  setTimeout(function() {
    doc['custom_is_student_user'] = isStudent;
    doc['custom_is_enrolled_student'] = (roleCtx.is_enrolled_student === true);
    if (isStudent && sctx) {
      var sfields = [
        'custom_student_name', 'custom_student_id', 'custom_programme',
        'custom_current_year', 'custom_current_term',
        'custom_contact_number', 'custom_hostel', 'custom_room_no'
      ];
      sfields.forEach(function(f) { doc[f] = sctx[f] || ''; });
    }
    if (doc['ticket_type'] === 'Attendance Condonation Under AER') {
      applyCourseOptions();
    }
    if (ISSUE_TICKET_TYPES.includes(doc['ticket_type'])) {
      applyIssueOptionsFor(doc['ticket_type']);
    }
  }, 50);

  // ── 3. Student / other-role onChange handlers ────────────────────────────
  return {
    onChange: {
      ticket_type: function(value) {
        doc['custom_type_of_issue'] = '';
        if (value === 'Attendance Condonation Under AER') {
          applyCourseOptions();
        }
        if (value === 'Transcript Request') {
          // Only one transcript type is offered from Helpdesk today —
          // pre-select it so the student doesn't have to open the dropdown.
          doc['custom_transcript_type'] = 'Final Transcript';
        }
        applyIssueOptionsFor(value);
        if (typeof setAbout === 'function') setAbout(TICKET_TYPE_NOTES[value] || '');
      }
    }
  };
}
